import{_ as s,a0 as r,w as i,s as d,ao as l,I as n,x as o,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"安卓编年史（7） | LCTT x X-CMD","titleTemplate":false,"description":"安卓编年史（7） | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓编年史（7） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓编年史（7） | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/07 - The history of Android","title":"安卓编年史（7）","tag":"The history of Android","desc":""},"relativePath":"The history of Android/07 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/07 - The history of Android.md"};function u(g,t,T,f,h,A){const p=r("Link");return i(),d("div",null,[t[23]||(t[23]=l('<h1 id="安卓编年史-7" tabindex="-1">安卓编年史（7） <a class="header-anchor" href="#安卓编年史-7" aria-label="Permalink to “安卓编年史（7）”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/01/email2lol.png" alt="电子邮件应用的所有界面。前两张截图展示了标签/收件箱结合的视图，最后一张截图展示了一封邮件。"></p><p><em>电子邮件应用的所有界面。前两张截图展示了标签/收件箱结合的视图，最后一张截图展示了一封邮件。 [Ron Amadeo供图]</em></p><p>邮件视图是——令人惊讶的！居然是白色。安卓的电子邮件应用从历史角度来说算是个打了折扣的Gmail应用，你可以在这里看到紧密的联系。读邮件以及写邮件视图几乎没有任何修改地就从Gmail那里直接取过来使用。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/IM2.png" alt="即时通讯应用。截图展示了服务提供商选择界面，朋友列表，以及一个对话。"></p><p><em>即时通讯应用。截图展示了服务提供商选择界面，朋友列表，以及一个对话。[Ron Amadeo供图]</em></p><p>在Google Hangouts之前，甚至是Google Talk之前，就有了“IM”——安卓1.0带来的唯一一个即时通讯客户端。令人惊奇的是，它支持多种IM服务：用户可以从AIM，Google Talk，Windows Live Messenger以及Yahoo中挑选。还记得操作系统开发者什么时候关心过互通性吗？</p><p>朋友列表是黑色背景界面，如果在聊天中则带有白色聊天气泡。状态用一个带颜色的圆形来指示，右侧的小安卓机器人指示出某人正在使用移动设备。IM应用相比Google Hangouts远比它有沟通性，这真是十分神奇的。绿色代表着某人正在使用设备并且已经登录，黄色代表着他们登录了但处于空闲状态，红色代表他们手动设置状态为忙，不想被打扰，灰色表示离线。现在Hangouts只显示用户是否打开了应用。</p><p>聊天对话界面明显基于信息应用，聊天的背景从白色和蓝色被换成了白色和绿色。但是没人更改信息输入框的颜色，所以加上橙色的高亮效果，界面共使用了白色，绿色，蓝色和橙色。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/yt5000.png" alt="安卓1.0上的YouTube。截图展示了主界面，打开菜单的主界面，分类界面，视频播放界面。"></p><p><em>安卓1.0上的YouTube。截图展示了主界面，打开菜单的主界面，分类界面，视频播放界面。[Ron Amadeo供图]</em></p><p>以G1的320p屏幕和3G网络速度，YouTube可能不会有今天这样的手机上的表现，但谷歌的视频服务在安卓1.0上就被置入发布了。主界面看起来就像是安卓市场调整过的版本，顶部带有一个横向滚动选择部分，下面有垂直滚动分类列表。谷歌的一些分类选择还真是奇怪：“最热门”和“最多观看”有什么区别？</p>',12)),n("p",null,[t[1]||(t[1]=o("这是一个谷歌没有意识到YouTube最终能达到多庞大的标志——有一个视频分类是“最近更新”。在今天，每分钟有",-1)),e(p,{href:"http://www.youtube.com/yt/press/statistics.html"},{default:a(()=>[...t[0]||(t[0]=[o("100小时时长的视频",-1)])]),_:1}),t[2]||(t[2]=o("上传到Youtube上，如果这个分类能正常工作的话，它会是一个快速滚动的视频列表，快到以至于变为一片无法阅读的模糊。",-1))]),t[24]||(t[24]=l('<p>菜单含有搜索，喜爱，分类，设置。设置（没有该图片）是有史以来最简陋的，只有个清除搜索历史的选项。分类都是一样的平淡，仅仅是个黑色的文本列表。</p><p>最后一张截图展示了视频播放界面，只支持横屏模式。尽管自动隐藏的播放控制有个进度条，但它还是很奇怪地包含了后退和前进按钮。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/yt3.png" alt="YouTube的视频菜单，描述页面，评论。"></p><p><em>YouTube的视频菜单，描述页面，评论。[Ron Amadeo供图]</em></p><p>每个视频的更多选项可以通过点击菜单按钮来打开。在这里你可以把视频标记为“喜爱”，查看详细信息，以及阅读评论。所有的这些界面，和视频播放一样，是锁定横屏模式的。</p><p>然而“共享”不会打开一个对话框，它只是向Gmail邮件中加入了视频的链接。想要把链接通过短信或即时消息发送给别人是不可能的。你可以阅读评论，但是没办法评价他们或发表自己的评论。你同样无法给视频评分或赞。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/camera.png" alt="相机应用的拍照界面，菜单，照片浏览模式。"></p><p><em>相机应用的拍照界面，菜单，照片浏览模式。[Ron Amadeo供图]</em></p><p>在实体机上跑真正的安卓意味着相机功能可以正常运作，即便那里没什么太多可关注的。左边的黑色方块是相机的界面，原本应该显示取景器图像，但SDK的截图工具没办法捕捉下来。G1有个硬件实体的拍照键（还记得吗？），所以相机没必要有个屏幕上的快门键。相机没有曝光，白平衡，或HDR设置——你可以拍摄照片，仅此而已。</p><p>菜单按钮显示两个选项：跳转到相册应用和带有两个选项的设置界面。第一个设置选项是是否给照片加上地理标记，第二个是在每次拍摄后显示提示菜单，你可以在上面右边看到截图。同样的，你目前还只能拍照——还不支持视频拍摄。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/calviews.png" alt="日历的月视图，打开菜单的周视图，日视图，以及日程。"></p><p><em>日历的月视图，打开菜单的周视图，日视图，以及日程。[Ron Amadeo供图]</em></p><p>就像这个时期的大多数应用一样，日历的主命令界面是菜单。菜单用来切换视图，添加新事件，导航至当天，选择要显示的日程，以及打开设置。菜单扮演着每个单独按钮的入口的作用。</p><p>月视图不能显示约会事件的文字。每个日期旁边有个侧边，约会会显示为侧边上的绿色部分，通过位置来表示约会是在一天中的什么时候。周视图同样不能显示预约文字——G1的320×480的显示屏像素还不够密——所以你会在日历中看到一个带有颜色指示条的白块。唯一一个显示文字的是日程和日视图。你可以用滑动来切换日期——左右滑动切换周和日，上下滑动切换月份和日程。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/settings.png" alt="设置主界面，无线设置，关于页面的底部。"></p><p><em>设置主界面，无线设置，关于页面的底部。[Ron Amadeo供图]</em></p><p>安卓1.0最终带来了设置界面。这个界面是个带有文字的黑白界面，粗略地分为各个部分。每个列表项边上的下箭头让人误以为点击它会展开折叠的更多东西，但是触摸列表项的任何位置只会加载下一屏幕。所有的界面看起来确实无趣，都差不多一样，但是嘿，这可是设置啊。</p><p>任何带有开/关状态的选项都使用了卡通风格的复选框。安卓1.0最初的复选框真是奇怪——就算是在“未选中”状态时，它们还是有个灰色的勾选标记在里面。安卓把勾选标记当作了灯泡，打开时亮起来，关闭的时候变得黯淡，但这不是复选框的工作方式。然而我们最终还是见到了“关于”页面。安卓1.0运行Linux内核2.6.25版本。</p><p>设置界面意味着我们终于可以打开安全设置并更改锁屏。安卓1.0只有两种风格，安卓0.9那样的灰色方形锁屏，以及需要你在9个点组成的网格中画出图案的图形解锁。像这样的滑动图案相比PIN码更加容易记忆和输入，尽管它没有增加多少安全性。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/grabbag.png" alt="语音拨号，图形锁屏，电池低电量警告，时间设置。"></p><p><em>语音拨号，图形锁屏，电池低电量警告，时间设置。[Ron Amadeo供图]</em></p><p>语音功能和语音拨号一同来到了1.0。这个特性以各种功能实现在AOSP徘徊了一段时间，然而它是一个简单的拨打号码和联系人的语音命令应用。语音拨号是个和谷歌未来的语音产品完全无关的应用，它的工作方式和非智能机上的语音拨号一样。</p><p>关于最后一个值得注意的，当电池电量低于百分之十五的时候会触发低电量弹窗。这是个有趣的图案，它把电源线错误的一端插入手机。谷歌，那可不是（现在依然不是）手机应该有的充电方式。</p><p>安卓1.0是个伟大的开端，但是功能上仍然有许多缺失。强制配备了实体键盘和大量硬件按钮，因为不带有十字方向键或轨迹球的安卓设备依然不被允许销售。另外，基本的智能手机功能比如自动旋转依然缺失。内置应用不可能像今天这样通过安卓市场来更新。所有的谷歌系应用和系统交织在一起。如果谷歌想要升级一个单独的应用，需要通过运营商推送整个系统的更新。安卓依然还有许多工作要做。</p><h3 id="安卓1-1——第一个真正的增量更新" tabindex="-1">安卓1.1——第一个真正的增量更新 <a class="header-anchor" href="#安卓1-1——第一个真正的增量更新" aria-label="Permalink to “安卓1.1——第一个真正的增量更新”">​</a></h3><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/11.png" alt="安卓1.1的所有新特性：语音搜索，安卓市场付费应用支持，谷歌纵横，设置中的新“系统更新”选项。"></p><p><em>安卓1.1的所有新特性：语音搜索，安卓市场付费应用支持，谷歌纵横，设置中的新“系统更新”选项。[Ron Amadeo供图]</em></p>',27)),n("p",null,[t[4]||(t[4]=o("安卓1.0发布四个半月后，2009年2月，安卓在安卓1.1中得到了它的第一个公开更新。系统方面没有太多变化，谷歌向1.1中添加的新东西现如今也都已被关闭。谷歌语音搜索是安卓向云端语音搜索的第一个突击，它在应用抽屉里有自己的图标。尽管这个应用已经不能与谷歌服务器通讯，你可以",-1)),e(p,{href:"http://www.youtube.com/watch?v=y3z7Tw1K17A"},{default:a(()=>[...t[3]||(t[3]=[o("在iPhone上",-1)])]),_:1}),t[5]||(t[5]=o("看到它以前是怎么工作的。它还没有语音操作，但你可以说出想要搜索的，结果会显示在一个简单的谷歌搜索中。",-1))]),t[25]||(t[25]=n("p",null,"安卓市场添加了对付费应用的支持，但是就像beta客户端中一样，这个版本的安卓市场已经不能连接Google Play服务器。我们最多能够看到分类界面，你可以在免费应用、付费应用和全部应用中选择。",-1)),n("p",null,[t[7]||(t[7]=o("地图添加了",-1)),e(p,{href:"http://arstechnica.com/information-technology/2009/02/google-tries-location-based-social-networking-with-latitude/"},{default:a(()=>[...t[6]||(t[6]=[o("谷歌纵横",-1)])]),_:1}),t[8]||(t[8]=o("，一个向朋友分享自己位置的方法。纵横在几个月前为了支持Google+而被关闭并且不再能够工作。地图菜单里有个纵横的选项，但点击它现在只会打开一个带载入中圆圈的画面，并永远停留在这里。",-1))]),t[26]||(t[26]=n("p",null,"安卓世界的系统更新来得更加迅速——或者至少是一条在运营商和OEM推送之前获得更新的途径——谷歌也在“关于手机”界面添加了检查系统更新按钮。",-1)),t[27]||(t[27]=n("hr",null,null,-1)),t[28]||(t[28]=n("p",null,[n("img",{src:"http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg",alt:"Ron Amadeo"})],-1)),n("p",null,[e(p,{href:"http://arstechnica.com/author/ronamadeo"},{default:a(()=>[...t[9]||(t[9]=[o("Ron Amadeo",-1)])]),_:1}),t[10]||(t[10]=o(" / Ron是Ars Technica的评论编缉，专注于安卓系统和谷歌产品。他总是在追寻新鲜事物，还喜欢拆解事物看看它们到底是怎么运作的。",-1))]),n("p",null,[e(p,{href:"https://twitter.com/RonAmadeo"},{default:a(()=>[...t[11]||(t[11]=[o("@RonAmadeo",-1)])]),_:1})]),t[29]||(t[29]=n("hr",null,null,-1)),n("p",null,[t[13]||(t[13]=o("via: ",-1)),e(p,{href:"http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/7/"},{default:a(()=>[...t[12]||(t[12]=[o("http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/7/",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=o("译者：",-1)),e(p,{href:"https://github.com/alim0x"},{default:a(()=>[...t[14]||(t[14]=[o("alim0x",-1)])]),_:1}),t[17]||(t[17]=o(" 校对：",-1)),e(p,{href:"https://github.com/wxy"},{default:a(()=>[...t[15]||(t[15]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=o("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[18]||(t[18]=[o("LCTT",-1)])]),_:1}),t[21]||(t[21]=o(" 原创翻译，",-1)),e(p,{href:"http://linux.cn/"},{default:a(()=>[...t[19]||(t[19]=[o("Linux中国",-1)])]),_:1}),t[22]||(t[22]=o(" 荣誉推出",-1))])])}const x=s(m,[["render",u]]);export{y as __pageData,x as default};
